package com.example;

import junit.framework.TestCase;
import junit.framework.TestSuite;

public class MyJUnit3Test extends TestCase {

    public void testFirstFeature() {
        // Test logic
        junit.framework.Assert.assertTrue("Test failed", true);
    }

    protected void testHelperMethod() { // Not public, so should not be annotated
        junit.framework.Assert.fail("This is a helper, not a test");
    }

    // A method that is not a test due to name
    public void setupData() {}

    public static junit.framework.Test suite() {
        return new TestSuite(MyJUnit3Test.class);
    }
}

afterExample:
package com.example;

import junit.framework.TestCase;
import junit.framework.TestSuite;
import org.junit.Test; // Added import for @Test

public class MyJUnit3Test extends TestCase {

    @Test // Annotation added
    public void testFirstFeature() {
        // Test logic
        junit.framework.Assert.assertTrue("Test failed", true);
    }

    protected void testHelperMethod() { // Remains unchanged, as it's not public
        junit.framework.Assert.fail("This is a helper, not a test");
    }

    // A method that is not a test due to name
    public void setupData() {}

    public static junit.framework.Test suite() {
        return new TestSuite(MyJUnit3Test.class);
    }
}

negativeExample:
package com.example;

// Does not extend TestCase
public class MyPlainClass {

    public void testSomething() { // Should not be annotated as class does not extend TestCase
        System.out.println("This is just a method named testSomething");
    }

    public static void testStaticMethod() { // Is static, so should not be annotated
        System.out.println("This is a static method named testStaticMethod");
    }

    public void notATestMethod() { // Does not start with "test", so should not be annotated
        System.out.println("This is not a test method");
    }
}
